pragma cashscript ^0.14.0;

/**
 * AssetManager: Holds individual assets for funds
 *
 * This contract gates asset access during redemption (outflow) transactions.
 * Amount verification is performed by the TransactionManager contract.
 * Each asset in a fund has a dedicated AssetManager contract instance.
 *
 * Parameters:
 *   outflowToken: Token category that authorizes redemption
 *   fundHash: Hash of fund parameters (prevents spending wrong fund's assets)
 *   assetCategory: The specific asset category this contract holds
 *                  (0x00...00 = Bitcoin, else = token category)
 *   transactionManager: Locking bytecode of this fund's TransactionManager (authenticates the outflow)
 *   linkedAsset: Locking bytecode of the AssetManager redeemed just before this one
 *                (satoshis first, then assets by ascending category), empty for the first
 */
contract AssetManager(bytes32 outflowToken, bytes32 fundHash, bytes32 assetCategory, bytes transactionManager, bytes linkedAssetManager)
{
    /**
     * release(): Releases held assets when outflow is authorized
     *
     * AssetManager relies on TransactionManager for redeeming asset amount verification.
     * To release, checking for the TransactionManager's outflow or linking w/ a previous AssetManager.
     *
     * Ensures:
     * - Asset type is verified (Bitcoin or tokens)
     * - Previous input spends from this contract or the linked AssetManager, which release() themselves
     * - Otherwise, the outflow token is spent from this fund's TransactionManager (correct redemption)
     */
    function release() {
        //
        // Verify this spends the correct asset
        // Bitcoin for 0x00... otherwise verify token category
        if(assetCategory == toPaddedBytes(0, 32)) {
            require(tx.inputs[this.activeInputIndex].tokenCategory == 0x);
        } else {
            require(tx.inputs[this.activeInputIndex].tokenCategory == assetCategory);
        }

        //
        // Check if the previous input is this AssetManager or the linked AssetManager for this fund
        bytes prevLockingBytecode = tx.inputs[this.activeInputIndex - 1].lockingBytecode;
        bool linked = prevLockingBytecode == tx.inputs[this.activeInputIndex].lockingBytecode || (prevLockingBytecode == linkedAssetManager && linkedAssetManager != 0x);

        //
        // Must have redemption signal or previous AssetManager contract
        if(!linked) {
            //
            // Tip of the asset chain
            // Find the transaction manager w/ outflow token
            // Check all inputs leading to outflow, should be the same or one a single input for fee contract
            // The lock to match is taken from the input just before this one, by position: an empty lock (0x) is a
            // valid locking bytecode, so the value can't mark "not recorded yet" or it would let a later lock be adopted
            bytes prevFundManager = 0x;
            bool prevOutflow = false;
            int inputIndex = this.activeInputIndex - 1;
            while(inputIndex >= 0 && !prevOutflow) {
                if(tx.inputs[inputIndex].tokenCategory == outflowToken) {
                    require(tx.inputs[inputIndex].lockingBytecode == transactionManager);
                    require(tx.inputs[inputIndex].nftCommitment.slice(33, 65) == fundHash); // type 0x02 + fund category 32 bytes + fund hash 32 bytes
                    prevOutflow = true;
                } else if(inputIndex == this.activeInputIndex - 1) {
                    prevFundManager = tx.inputs[inputIndex].lockingBytecode;
                } else {
                    require(prevFundManager == tx.inputs[inputIndex].lockingBytecode || tx.inputs[inputIndex - 1].tokenCategory == outflowToken);
                }
                inputIndex = inputIndex - 1;
            }
            require(prevOutflow);
        }
    }
}
